class HomeScreen extends ConsumerStatefulWidget{const HomeScreen({super.key});@override ConsumerState<HomeScreen> createState()=>_State();}class _State extends ConsumerState<HomeScreen>{List<VehicleListing> items=[];bool loading=true;String? message;double radius=25;String? category;final emergency=['Three Wheeler','Car','Van','Motorbike','Lorry','Pickup','Ambulance Contact','Tow Vehicle','Driver Only'];@override void initState(){super.initState();load();}Future<void> load()async{setState(()=>loading=true);final result=await LocationService().current();var lat=result.position?.latitude,lng=result.position?.longitude;if(lat==null){lat=6.9271;lng=79.8612;message='${result.message} Showing results near Colombo as a manual fallback.';}try{items=await ref.read(listingRepositoryProvider).nearby(latitude:lat,longitude:lng!,radius:radius,category:category);}catch(_){message='Could not load listings. Check your connection and try again.';}if(mounted)setState(()=>loading=false);}@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('NearRide',style:TextStyle(fontWeight:FontWeight.bold)),Text('Vehicles around you',style:TextStyle(fontSize:12,fontWeight:FontWeight.normal))]),actions:[IconButton(onPressed:()=>context.push('/login'),icon:const Icon(Icons.person_outline)),const SizedBox(width:8)]),floatingActionButton:FloatingActionButton.extended(onPressed:()=>context.push('/provider'),icon:const Icon(Icons.add),label:const Text('List a vehicle')),bottomNavigationBar:NavigationBar(selectedIndex:0,destinations:const [NavigationDestination(icon:Icon(Icons.home_outlined),selectedIcon:Icon(Icons.home),label:'Home'),NavigationDestination(icon:Icon(Icons.search),label:'Search'),NavigationDestination(icon:Icon(Icons.favorite_outline),label:'Saved'),NavigationDestination(icon:Icon(Icons.person_outline),label:'Account')]),body:RefreshIndicator(onRefresh:load,child:ListView(padding:const EdgeInsets