)else ...items.map((x)=>Padding(padding:const EdgeInsets.only(bottom:12),child:ListingCard(listing:x))),])));}class _Search extends SearchDelegate{final suggestions=['Van','Car','Driver only','Tow vehicle','Pickup'];@override List<Widget> buildActions(BuildContext c)=>[IconButton(onPressed:()=>query='',icon:const Icon(Icons.clear))];@override Widget buildLeading(BuildContext c)=>BackButton(onPressed:()=>close(c,null));@override Widget buildResults(BuildContext c)=>Center(child:Text('Use filters on the nearby screen for “$query”.'));@override Widget buildSuggestions(BuildContext c)=>ListView(children:suggestions.where((x)=>x.toLowerCase().contains(query.toLowerCase())).map((x)=>ListTile(title:Text(x),leading:const Icon(Icons.search),onTap:(){query=x;showResults(c);})).toList());}
